import axios from "axios";

const API = axios.create({ baseURL: "http://localhost:3001" }); // Replace with your backend URL

// Add Authorization header for protected routes
API.interceptors.request.use((req) => {
    const token = localStorage.getItem("token"); // Get the token from localStorage
    if (token) {
        req.headers.Authorization = `Bearer ${token}`;
    }
    return req;
});

// Authentication APIs
export const loginUser = async ({ username, password }) => {
    try {
        const response = await API.post('/api/login', { username, password });
        // Save the token to localStorage after login
        if (response.data.token) {
            localStorage.setItem("token", response.data.token);
        }
        return response.data; // Assuming response structure: { data: { token, user }}
    } catch (error) {
        console.error("Login failed:", error);
        throw error; // Rethrow the error so you can handle it in the component
    }
};

// Franchise APIs
export const createFranchise = (data) => API.post("/franchises", data);
export const getFranchises = () => API.get("/dashboard");
export const deleteFranchise = (id) => API.delete(`/franchises/${id}`);
export const updateFranchise = (id, data) => API.put(`/franchises/${id}`, data); // New function for updating a franchise

// User APIs
export const createUser = async (data) => {
    const { username, password, name, role, franchiseId } = data;
    try {
        const response = await API.post("/users", { username, password, name, role, franchiseId });
        return response.data;
    } catch (error) {
        console.error("Error creating user:", error);
        throw error;
    }
};

// Get users API
export const getUsers = async () => {
    try {
        const response = await API.get("/users");
        return response.data;
    } catch (error) {
        console.error("Error fetching users:", error);
        throw error;
    }
};

// Delete user by ID
export const deleteUser = async (userId) => {
    try {
        const response = await API.delete(`/users/${userId}`);
        return response.data;
    } catch (error) {
        console.error("Error deleting user:", error);
        throw error;
    }
};

// Update user by ID
export const updateUser = async (userId, userData) => {
    try {
        const response = await API.put(`/users/${userId}`, userData);
        return response.data;
    } catch (error) {
        console.error("Error updating user:", error);
        throw error;
    }
};

// Exam Data APIs

// Update Exam Data
export const updateExamData = async (exam) => {
    const { franchiseId, _id, ...examData } = exam;
    if (!franchiseId || !_id) {
        throw new Error('Invalid franchiseId or examId');
    }
    const token = localStorage.getItem("token");
    if (!token) {
        throw new Error("No authorization token found.");
    }
    try {
        const response = await axios.put(
            `http://localhost:3001/franchises/${franchiseId}/exam-data/${_id}`,
            examData,
            {
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            }
        );
        return response.data;
    } catch (error) {
        console.error("Error updating exam data:", error);
        throw error;
    }
};

// Delete Exam Data
export const deleteUserExamData = async (franchiseId, examId) => {
    const token = localStorage.getItem("token");
    if (!token) {
        throw new Error("No authorization token found.");
    }

    try {
        const response = await axios.delete(
            `http://localhost:3001/franchises/${franchiseId}/exam-data/${examId}`,
            {
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            }
        );
        return response.data;
    } catch (error) {
        console.error("Error deleting exam data:", error);
        throw error;
    }
};

// Get associated franchises for logged-in user
export const getAssociatedFranchises = async () => {
    try {
        const response = await API.get('/franchises/associated'); // Endpoint for getting associated franchises
        return response.data;
    } catch (error) {
        console.error("Error fetching associated franchises:", error);
        throw error;
    }
};

// Create Exam Data for a franchise
export const createUserExamData = async (examData) => {
    const token = localStorage.getItem('token');
    if (!token) {
        throw new Error('No authorization token found.');
    }

    try {
        const response = await axios.post(
            `http://localhost:3001/franchises/${examData.franchiseId}/exam-data`,
            examData,
            {
                headers: {
                    Authorization: `Bearer ${token}`,
                },
            }
        );
        return response.data;
    } catch (error) {
        console.error("Error creating exam data:", error);
        throw error;
    }
};
